"""منابع هر حوزه: 10 مقاله + 10 کتاب + 10 ویدیو"""
from dataclasses import dataclass, field
from typing import List, Literal

@dataclass
class Resource:
    domain_id: str
    kind: Literal["article","book","video"]
    title: str
    url: str = ""
    author: str = ""
    year: str = ""
    lang: str = "en"
    summary_fa: str = ""
    tags: List[str] = field(default_factory=list)

RESOURCES: List[Resource] = []

def add(domain_id, kind, title, url="", author="", year="", lang="en", summary_fa="", tags=None):
    RESOURCES.append(Resource(domain_id, kind, title, url, author, year, lang, summary_fa, tags or []))

